function Icon({ name, size = 20, className = '' }: { name: IconName; size?: number; className?: string }) {
  const paths: Record<IconName, React.ReactNode> = {
    book: <><path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Z"/><path d="M12 5v15"/></>,
    mail: <><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/></>,
    arrow: <><path d="M4 12h16m-6-6 6 6-6 6"/></>,
    plus: <path d="M12 5v14M5 12h14"/>, check: <path d="m5 12 4 4L19 6"/>, close: <path d="m6 6 12 12M6 18 18 6"/>,
    search: <><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></>, chevron: <path d="m9 5 7 7-7 7"/>,
    settings: <><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/></>,
    refresh: <><path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6M4 13a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/></>,
    upload: <><path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/></>, clock: <><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,
    link: <><path d="m10 13 4-4m-5 7-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 0 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/></>,
    eye: <><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></>,
    pause: <><path d="M8 5v14M16 5v14"/></>, sun: <><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></>,
  };
  return <svg width={size} height={size} className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.55" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>;
}

async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const response = await fetch(path, { credentials: 'same-origin', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...options.headers } });
  const body: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const error = body as { error?: string; message?: string } | null;
    throw new Error(error?.error ?? error?.message ?? `Request failed (${response.status}). Please try again.`);
  }
  return body as T;
}
function mutate<T>(path: string, body?: unknown, method = 'POST') { return api<T>(path, { method, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) }); }
function readableDate(value: string | null, timezone?: string, includeTime = true) {
  if (!value || !Number.isFinite(Date.parse(value))) return 'Not yet';
  return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', ...(includeTime ? { hour: 'numeric', minute: '2-digit' } : {}), ...(timezone ? { timeZone: timezone } : {}) }).format(new Date(value));
}
function relativeDate(value: string | null) {
  if (!value) return 'No import yet';
  const hours = Math.floor((Date.now() - new Date(value).getTime()) / 3600000);
  return hours < 1 ? 'Less than an hour ago' : hours < 24 ? `${hours} hour${hours === 1 ? '' : 's'} ago` : readableDate(value, undefined, false);
}
function scheduleTime(preferences: Preferences) {
  if (!/^\d{2}:\d{2}$/.test(preferences.localTime)) return 'your chosen time';
  const [h, m] = preferences.localTime.split(':').map(Number);
  return `${h % 12 || 12}:${String(m).padStart(2, '0')} ${h >= 12 ? 'pm' : 'am'}`;
}
function usePage() {
  const [location, setLocation] = useState(() => window.location.pathname + window.location.search);
  useEffect(() => { const onPop = () => setLocation(window.location.pathname + window.location.search); window.addEventListener('popstate', onPop); return () => window.removeEventListener('popstate', onPop); }, []);
  const navigate = useCallback((to: string) => { window.history.pushState({}, '', to); setLocation(to); window.scrollTo(0, 0); }, []);
  return { path: location.split('?')[0], search: new URLSearchParams(location.split('?')[1] ?? ''), navigate };
}
function ErrorMessage({ error, onRetry }: { error: string; onRetry?: () => void }) { return <div role="alert" className="notice error"><span>{error}</span>{onRetry && <button className="text-button" onClick={onRetry}>Try again</button>}</div>; }
function Loading({ label = 'Opening your library…' }: { label?: string }) { return <div className="loading" role="status"><span className="spinner"/>{label}</div>; }
function Brand({ onClick }: { onClick?: () => void }) { return <button className="brand" onClick={onClick} aria-label="Writefool home"><span className="brand-mark"><Icon name="book" size={23}/></span>writefool<span className="brand-period">.</span></button>; }
function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1>{description && <p className="page-description">{description}</p>}</div>{action}</div>; }
function Modal({ title, description, children, onClose, wide }: { title: string; description?: string; children: React.ReactNode; onClose: () => void; wide?: boolean }) {
  const dialog = useRef<HTMLDialogElement>(null);
  useEffect(() => { const d = dialog.current; d?.showModal(); return () => { d?.close(); }; }, []);
  return <dialog ref={dialog} className={`modal ${wide ? 'modal-wide' : ''}`} onCancel={onClose} onClick={e => { if (e.target === e.currentTarget) { const r = e.currentTarget.getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) onClose(); } }} aria-labelledby="modal-title"><div className="modal-heading"><div><h2 id="modal-title">{title}</h2>{description && <p>{description}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Close dialog"><Icon name="close"/></button></div>{children}</dialog>;
}

function Login({ config, onLogin }: { config: Config; onLogin: () => void }) {
  const [email, setEmail] = useState(''); const [busy, setBusy] = useState(false); const [sent, setSent] = useState(false); const [error, setError] = useState('');
  async function signIn(e: React.FormEvent) {
    e.preventDefault(); setBusy(true); setError('');
    try { await mutate('/api/auth/sign-in/magic-link', { email, callbackURL: window.location.origin + '/', timezone: Intl.DateTimeFormat().resolvedOptions().timeZone }); setSent(true); } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  }
  async function devLogin() { setBusy(true); setError(''); try { await mutate('/api/dev/login', { timezone: Intl.DateTimeFormat().resolvedOptions().timeZone }); onLogin(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  return <div className="login-layout"><header className="login-header"><Brand/><span className="small-label">A LITTLE RETURN TO WHAT MATTERS</span></header><main className="login-main"><section className="login-story"><p className="eyebrow"><span className="tiny-star">✳</span> FOR THE THOUGHTFUL READER</p><h1>The good parts,<br/>worth <em>returning to.</em></h1><p className="login-intro">You underlined it for a reason. Let the passages you loved find their way back to you, one quiet email at a time.</p><div className="ritual-illustration" aria-hidden="true"><div className="illustration-page back-page"></div><div className="illustration-page front-page"><span className="illustration-quote">“</span><div className="illustration-line highlighted"></div><div className="illustration-line highlighted short"></div><div className="illustration-line"></div><div className="illustration-line shorter"></div><span className="illustration-book">A thought worth keeping.</span></div><div className="illustration-stamp"><Icon name="mail" size={29}/></div><div className="handwritten">From your books.<br/>Back to you.</div></div><div className="login-details"><span><Icon name="book" size={16}/> Your Kindle highlights</span><span><Icon name="clock" size={16}/> Your own rhythm</span></div></section><section className="login-card"><span className="card-kicker">WELCOME TO WRITEFOOL</span>{sent ? <><span className="round-icon"><Icon name="mail" size={25}/></span><h2>Check your inbox.</h2><p>We've requested a sign-in link for <strong>{email}</strong>. If this is the configured account, your link will arrive shortly.</p><p className="muted small">The link is single-use and expires soon. You can close this tab once you've opened it.</p><button className="button secondary full" onClick={() => setSent(false)}>Use a different email</button></> : <><h2>Make room for<br/>a little rediscovery.</h2><p>Sign in to connect your books and begin a reading ritual that fits your life.</p><form onSubmit={signIn}><label htmlFor="email">Your email address</label><input id="email" type="email" autoComplete="email" placeholder="you@example.com" value={email} onChange={e => setEmail(e.target.value)} required disabled={busy}/><button className="button primary full" disabled={busy || !config.configured}>{busy ? 'One moment…' : 'Send me a sign-in link'}<Icon name="arrow" size={18}/></button></form><p className="login-footnote">No password to remember. Just your books,<br/>and a little time with them.</p></>}{error && <ErrorMessage error={error}/>} {!config.configured && <div className="notice">Email sign-in needs the account and sending domain configured. See the project setup guide.</div>}{config.development && <div className="dev-panel"><span className="dev-badge">LOCAL DEVELOPMENT</span><p>Explore the app locally without sending an email.</p><button className="text-button" onClick={devLogin} disabled={busy}>Enter development account <Icon name="arrow" size={16}/></button></div>}</section></main><footer className="login-footer"><span>A small ritual. A lasting impression.</span><span>Made for the margins.</span></footer></div>;
}

function HighlightCard({ highlight, index, actions, compact = false }: { highlight: Highlight; index?: number; actions?: React.ReactNode; compact?: boolean }) {
  return <article className={`highlight-card ${compact ? 'compact' : ''} ${highlight.hidden ? 'is-hidden' : ''}`} id={`highlight-${highlight.id}`}><div className="highlight-top"><span className="small-label">{index !== undefined ? `${String(index + 1).padStart(2, '0')} / A PASSAGE TO REVISIT` : highlight.hidden ? 'HIDDEN FROM EMAILS' : 'FROM YOUR LIBRARY'}</span>{actions}</div><blockquote>{highlight.text}</blockquote>{highlight.note && <div className="highlight-note"><span>Your note</span><p>{highlight.note}</p></div>}<div className="highlight-source"><span className="mini-book"><Icon name="book" size={17}/></span><div><strong>{highlight.title}</strong><p>{highlight.author || 'Unknown author'}{highlight.location ? <><span className="separator">·</span>{highlight.location}</> : null}</p></div></div></article>;
}
function Home({ dashboard, refresh, navigate, development }: { dashboard: Dashboard; refresh: () => Promise<void>; navigate: (path: string) => void; development: boolean }) {
  const [preview, setPreview] = useState<DigestPreview | null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState(''); const [showEmail, setShowEmail] = useState(false); const [previewLoading, setPreviewLoading] = useState(true);
  const { preferences, totals, sync } = dashboard;
  const getPreview = useCallback(async () => { setPreviewLoading(true); setError(''); try { setPreview(await api<DigestPreview>('/api/digest/preview')); } catch (e) { setError((e as Error).message); } finally { setPreviewLoading(false); } }, []);
  useEffect(() => { void getPreview(); }, [getPreview, totals.highlights, totals.eligible, preferences.highlightCount]);
  async function sendTest() { setBusy(true); setNotice(''); setError(''); try { const result = await mutate<{ status: string }>('/api/digest/test'); setNotice(result.status === 'accepted' || result.status === 'delivered' ? 'Your test email is on its way. Your rediscovery history stays the same.' : `Test email ${result.status}. You can check its status below.`); await refresh(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function seed() { setBusy(true); setError(''); try { await mutate('/api/dev/seed'); await refresh(); await getPreview(); setNotice('Development sample passages added. These are public-domain excerpts for local testing.'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  return <><PageHeading eyebrow="YOUR READING RITUAL" title="Return to the good parts." description="A few familiar words. A fresh way to see them." action={<div className="date-note"><Icon name="sun" size={22}/><span>{new Intl.DateTimeFormat('en', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date())}</span></div>}/>{sync.status === 'login_required' && <div className="notice warning"><span><strong>Amazon needs you to sign in again.</strong> Your saved highlights can still be emailed. Open your Kindle notebook and run a sync from the extension.</span><a href="https://read.amazon.com/notebook" target="_blank" rel="noreferrer" className="text-button">Open Kindle <Icon name="arrow" size={16}/></a></div>}{error && <ErrorMessage error={error} onRetry={() => void getPreview()}/>} {notice && <div className="notice success" role="status"><Icon name="check" size={18}/>{notice}</div>}<div className="home-grid"><section className="edition"><div className="section-heading"><h2><Icon name="mail" size={19}/> Your next email</h2><span className="pill subtle">{preferences.enabled ? 'Scheduled' : 'Preview'}</span></div><div className="email-preview"><div className="email-masthead"><span className="eyebrow">THE WRITEFOOL LETTER</span><div className="masthead-rule"/><p>A moment with your books.</p><span className="small muted">{preview?.highlights.length ?? preferences.highlightCount} passages, chosen for you</span></div>{previewLoading ? <Loading label="Choosing a few good passages…"/> : preview?.highlights.length ? <>{preview.highlights.slice(0, 3).map((h, i) => <HighlightCard key={h.id} highlight={h} index={i} compact/>)}{preview.highlights.length > 3 && <p className="more-passages">And {preview.highlights.length - 3} more passage{preview.highlights.length - 3 === 1 ? '' : 's'} in the full email.</p>}<div className="email-end"><span>Until next time,</span><strong>writefool.</strong></div></> : <div className="empty-state email-empty"><div className="empty-books"><Icon name="book" size={38}/></div><h3>{totals.highlights ? 'Give a few passages room to return.' : <>Your next favorite thought<br/>is already in your books.</>}</h3><p>{totals.highlights ? 'Your highlights are hidden or their books are excluded. Include a few favorites to fill your next letter.' : <>Bring in your Kindle highlights and we'll make<br className="desktop-break"/> a little space for them here.</>}</p><button className="button primary" onClick={() => navigate(totals.highlights ? '/library' : '/connect')}>{totals.highlights ? 'Curate your library' : 'Connect your Kindle'} <Icon name="arrow" size={17}/></button>{!totals.highlights && <button className="text-button" onClick={() => navigate('/library?import=true')}>Or import a clippings file</button>}</div>}</div><div className="preview-actions"><span><Icon name="eye" size={16}/> A preview. Your reading history is unchanged.</span><div><button className="text-button" onClick={() => setShowEmail(true)} disabled={!preview?.highlights.length}>Full preview</button><button className="button secondary small-button" onClick={sendTest} disabled={busy || !preview?.highlights.length}><Icon name="mail" size={15}/>{busy ? 'Sending…' : 'Send a test'}</button></div></div></section><aside className="home-aside"><section className="rhythm-card"><div className="section-heading"><h2>Your rhythm</h2><Icon name="clock" size={20}/></div><p className="rhythm-count">{preferences.highlightCount}<span>highlights</span></p><p className="rhythm-frequency">every {preferences.intervalDays === 1 ? 'day' : `${preferences.intervalDays} days`} <span>at {scheduleTime(preferences)}</span></p><div className="next-delivery"><span className="small-label">NEXT DELIVERY</span><strong>{preferences.enabled ? readableDate(preferences.nextSendAt, preferences.timezone) : 'A moment of pause'}</strong><span className="muted small">{preferences.enabled ? preferences.timezone.replaceAll('_', ' ') : 'Enable delivery when you’re ready.'}</span></div><button className="button secondary full" onClick={() => navigate('/settings')}><Icon name="settings" size={16}/>{preferences.enabled ? 'Adjust your rhythm' : 'Set up delivery'}</button></section><section className="shelf-card"><div className="section-heading"><h2>Your bookshelf</h2><Icon name="book" size={19}/></div><div className="library-stats"><div><strong>{totals.books}</strong><span>books</span></div><div><strong>{totals.highlights}</strong><span>highlights</span></div></div><button className="text-button" onClick={() => navigate('/library')}>Wander through your library <Icon name="arrow" size={16}/></button></section><section className="sync-card"><div className="sync-title"><span className={`status-dot ${sync.status.startsWith('account_') || sync.status === 'error' || sync.status === 'login_required' ? 'amber' : sync.connected ? 'green' : ''}`}/><strong>{sync.status.startsWith('account_') ? 'Kindle sync paused' : sync.status === 'syncing' ? 'Kindle is syncing' : sync.status === 'login_required' ? 'Sign-in needed' : sync.connected ? 'Kindle connected' : 'Bring your Kindle along'}</strong></div><p>{sync.status === 'syncing' ? `${sync.progress}% imported. Your library is on its way.` : sync.status.startsWith('account_') || sync.status === 'error' ? (sync.message ?? 'The last sync ran into a problem.') : sync.connected ? `Last imported: ${relativeDate(sync.lastSuccessAt)}. New highlights arrive when Chrome is open.` : 'Connect once, and your highlights will feel right at home.'}</p><button className="text-button" onClick={() => navigate('/connect')}>{sync.connected ? 'Manage connection' : 'Connect Kindle'}<Icon name="arrow" size={15}/></button></section><div className="margin-note"><span>✳</span><p>Some things deserve<br/>a second reading.</p></div></aside></div>{dashboard.recentDigests.length > 0 && <section className="recent-section"><div className="section-heading"><h2>Recent letters</h2><span className="small muted">Your last few deliveries</span></div><div className="history-list">{dashboard.recentDigests.slice(0, 5).map(d => <div className="history-row" key={d.id}><span className="history-mail"><Icon name="mail" size={18}/></span><div><strong>{d.isTest ? 'A test letter' : 'Your highlight letter'}</strong><p>{readableDate(d.scheduledFor, preferences.timezone)} · {d.highlightCount} highlights</p>{d.error && <p className="error-text">{d.error}</p>}</div><span className={`pill ${['failed','uncertain','bounced','complained'].includes(d.status) ? 'warning-pill' : 'subtle'}`}>{d.status}</span></div>)}</div></section>}{development && totals.highlights === 0 && <div className="dev-footer"><span className="dev-badge">LOCAL DEVELOPMENT</span><button className="text-button" onClick={seed} disabled={busy}>Load public-domain sample passages</button></div>}{showEmail && preview && <Modal title="Your letter, in full" description={preview.subject} onClose={() => setShowEmail(false)} wide><iframe className="email-frame" title="Full email preview" srcDoc={preview.html} sandbox=""/></Modal>}</>;
}

function App() {
  const { path, search, navigate } = usePage(); const [config, setConfig] = useState<Config | null>(null); const [session, setSession] = useState<Session>(null); const [dashboard, setDashboard] = useState<Dashboard | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const refresh = useCallback(async () => { const data = await api<Dashboard>('/api/dashboard'); setDashboard(data); }, []);
  const initialize = useCallback(async () => { setLoading(true); setError(''); try { const [c, s] = await Promise.all([api<Config>('/api/config'), api<Session>('/api/auth/get-session')]); setConfig(c); setSession(s); if (s?.user) await refresh(); } catch (e) { setError((e as Error).message); } finally { setLoading(false); } }, [refresh]);
  useEffect(() => { void initialize(); }, [initialize]);
  useEffect(() => { if (!session?.user) return; const update = () => { if (document.visibilityState === 'visible') void refresh().catch(() => {}); }; document.addEventListener('visibilitychange', update); const interval = window.setInterval(update, 30000); return () => { document.removeEventListener('visibilitychange', update); window.clearInterval(interval); }; }, [session, refresh]);
  async function signOut() { try { await mutate('/api/auth/sign-out'); setSession(null); setDashboard(null); navigate('/'); } catch (e) { setError((e as Error).message); } }
  if (loading) return <div className="initial-loading"><Brand/><Loading label="A moment for your books…"/></div>;
  if (error && (!config || !dashboard && session?.user)) return <div className="initial-loading"><Brand/><ErrorMessage error={error} onRetry={() => void initialize()}/></div>;
  if (!session?.user || !dashboard) return config ? <Login config={config} onLogin={() => void initialize()}/> : <ErrorMessage error={error || 'Unable to reach the app.'} onRetry={() => void initialize()}/>;
  return <div className="app-shell"><header className="app-header"><div className="header-inner"><Brand onClick={() => navigate('/')}/><nav aria-label="Main navigation">{[{ path: '/', label: 'For you', icon: 'sun' }, { path: '/library', label: 'Your library', icon: 'book' }, { path: '/settings', label: 'Your rhythm', icon: 'settings' }].map(item => <a key={item.path} href={item.path} className={path === item.path ? 'active' : ''} aria-current={path === item.path ? 'page' : undefined} onClick={e => { if (!e.metaKey && !e.ctrlKey && !e.shiftKey && e.button === 0) { e.preventDefault(); navigate(item.path); } }}><Icon name={item.icon as IconName} size={16}/>{item.label}</a>)}</nav><div className="account-menu"><span className="account-avatar" title={dashboard.user.email}>{dashboard.user.email.slice(0, 1).toUpperCase()}</span><button className="text-button sign-out" onClick={signOut}>Sign out</button></div></div></header><main className="main-content">{error && <ErrorMessage error={error}/>} {path === '/library' ? <Library key={path} search={search} dashboard={dashboard} refresh={refresh} navigate={navigate}/> : path === '/settings' ? <Settings dashboard={dashboard} refresh={refresh} navigate={navigate}/> : path === '/connect' ? <Connect dashboard={dashboard} refresh={refresh}/> : path === '/' ? <Home dashboard={dashboard} refresh={refresh} navigate={navigate} development={!!config?.development}/> : <div className="empty-state"><h1>This page has wandered off.</h1><button className="button primary" onClick={() => navigate('/')}>Return home</button></div>}</main><footer className="app-footer"><span>writefool<span className="brand-period">.</span><span className="footer-divider">/</span>A small ritual. A lasting impression.</span><button className="text-button" onClick={() => navigate('/connect')}>Kindle connection <Icon name="arrow" size={14}/></button></footer></div>;
}

// Additional library, preferences, and pairing views share the same authenticated API.
function Library({ search, dashboard, refresh, navigate }: { search: URLSearchParams; dashboard: Dashboard; refresh: () => Promise<void>; navigate: (path: string) => void }) {
  const [books, setBooks] = useState<Book[]>([]); const [highlights, setHighlights] = useState<Highlight[]>([]); const [query, setQuery] = useState(''); const [bookId, setBookId] = useState(''); const [includeHidden, setIncludeHidden] = useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [busyId, setBusyId] = useState(''); const [showImport, setShowImport] = useState(search.get('import') === 'true'); const [notice, setNotice] = useState('');
  const focusedId = search.get('highlight');
  const loadBooks = useCallback(async () => { setBooks((await api<{ books: Book[] }>('/api/books')).books); }, []);
  useEffect(() => { void loadBooks().catch(e => setError((e as Error).message)); }, [loadBooks]);
  const loadHighlights = useCallback(async (signal?: AbortSignal) => {
    const params = new URLSearchParams(); if (bookId) params.set('bookId', bookId); if (query) params.set('q', query); if (includeHidden || focusedId) params.set('includeHidden', 'true');
    setLoading(true); setError('');
    try { const result = await api<{ highlights: Highlight[] }>(`/api/highlights?${params}`, { signal }); setHighlights(result.highlights); } catch (e) { if ((e as Error).name !== 'AbortError') setError((e as Error).message); } finally { if (!signal?.aborted) setLoading(false); }
  }, [bookId, query, includeHidden, focusedId]);
  useEffect(() => { const controller = new AbortController(); const timeout = setTimeout(() => void loadHighlights(controller.signal), query ? 250 : 0); return () => { clearTimeout(timeout); controller.abort(); }; }, [loadHighlights, query]);
  useEffect(() => { if (!loading && focusedId) { const timeout = setTimeout(() => { const element = document.getElementById(`highlight-${focusedId}`); element?.scrollIntoView({ behavior: 'smooth', block: 'center' }); element?.classList.add('focused-highlight'); }, 80); return () => clearTimeout(timeout); } }, [loading, focusedId]);
  async function hideHighlight(h: Highlight) { setBusyId(h.id); setError(''); try { await mutate(`/api/highlights/${h.id}`, { hidden: !h.hidden }, 'PATCH'); await Promise.all([loadHighlights(), refresh()]); } catch (e) { setError((e as Error).message); } finally { setBusyId(''); } }
  async function excludeBook(book: Book) { setBusyId(book.id); setError(''); try { await mutate(`/api/books/${book.id}`, { excluded: !book.excluded }, 'PATCH'); await Promise.all([loadBooks(), refresh()]); } catch (e) { setError((e as Error).message); } finally { setBusyId(''); } }
  const selectedBook = books.find(b => b.id === bookId);
  return <><PageHeading eyebrow="THE WORDS YOU KEPT" title="Your personal bookshelf." description="All the passages that made you stop and underline." action={<button className="button secondary" onClick={() => setShowImport(true)}><Icon name="upload" size={17}/>Import clippings</button>}/>{notice && <div className="notice success" role="status"><Icon name="check" size={18}/>{notice}</div>}{error && <ErrorMessage error={error} onRetry={() => { void loadBooks(); void loadHighlights(); }}/>}<div className="library-layout"><aside className="book-sidebar"><div className="section-heading"><h2>Your books</h2><span className="count-badge">{books.length}</span></div><button className={`book-filter all-books ${!bookId ? 'selected' : ''}`} onClick={() => setBookId('')}><span className="book-spine"><Icon name="book" size={18}/></span><span><strong>All highlights</strong><small>{dashboard.totals.highlights} saved passages</small></span></button><div className="book-list">{books.map((book, index) => <button className={`book-filter ${book.id === bookId ? 'selected' : ''} ${book.excluded ? 'excluded' : ''}`} key={book.id} onClick={() => setBookId(book.id)}><span className={`book-spine color-${index % 4}`}><Icon name="book" size={17}/></span><span><strong>{book.title}</strong><small>{book.highlightCount} highlight{book.highlightCount === 1 ? '' : 's'}{book.excluded ? ' · Excluded' : ''}</small></span></button>)}</div><div className="sidebar-tip"><Icon name="sun" size={20}/><p>Your books stay with you. Choose which ones visit your inbox.</p></div></aside><section className="library-content"><div className="library-toolbar"><div className="search-field"><Icon name="search" size={18}/><input type="search" aria-label="Search highlights" placeholder="Find a thought, a word, a passage…" value={query} onChange={e => setQuery(e.target.value)}/></div><label className="checkbox-label"><input type="checkbox" checked={includeHidden} onChange={e => setIncludeHidden(e.target.checked)}/>Show hidden</label></div>{selectedBook && <div className="selected-book"><div><p className="eyebrow">{selectedBook.source === 'kindle' ? 'KINDLE' : 'CLIPPINGS'}</p><h2>{selectedBook.title}</h2><p>{selectedBook.author || 'Unknown author'}</p></div><button className="button secondary small-button" onClick={() => void excludeBook(selectedBook)} disabled={busyId === selectedBook.id}>{selectedBook.excluded ? <Icon name="plus" size={15}/> : <Icon name="pause" size={15}/>}{selectedBook.excluded ? 'Include in emails' : 'Exclude from emails'}</button></div>}{selectedBook?.excluded && <div className="notice">This book is resting on the shelf. Its highlights will not appear in emails.</div>}{loading ? <Loading label="Turning the pages…"/> : highlights.length ? <><div className="results-count">{highlights.length} passage{highlights.length === 1 ? '' : 's'}{query ? ` matching “${query}”` : ''}</div><div className="highlights-list">{highlights.map(h => <HighlightCard key={h.id} highlight={h} actions={<button className="text-button hide-button" onClick={() => void hideHighlight(h)} disabled={busyId === h.id} aria-label={`${h.hidden ? 'Restore' : 'Hide'} highlight from ${h.title}`}>{h.hidden ? <><Icon name="plus" size={14}/>Restore</> : <>Hide from emails</>}</button>}/>)}</div></> : <div className="empty-state library-empty"><div className="empty-books"><Icon name="book" size={36}/></div><h2>{query ? 'No passages found.' : books.length ? 'A quiet corner of your library.' : 'Your bookshelf starts here.'}</h2><p>{query ? 'Try a different word, or choose another book.' : books.length ? 'Try another book or include hidden highlights.' : 'Connect Kindle or upload your clippings to bring the words you saved into one place.'}</p>{!books.length && <div className="empty-actions"><button className="button primary" onClick={() => navigate('/connect')}>Connect Kindle<Icon name="arrow" size={16}/></button><button className="button secondary" onClick={() => setShowImport(true)}>Import clippings</button></div>}</div>}</section></div>{showImport && <ClippingsImport books={books} onClose={() => setShowImport(false)} onImported={async result => { setNotice(`${result.imported} highlights imported, ${result.updated} updated. ${result.skipped ? `${result.skipped} unchanged or skipped.` : ''}`); await Promise.all([loadBooks(), loadHighlights(), refresh()]); }}/>}</>;
}

function ClippingsImport({ books, onClose, onImported }: { books: Book[]; onClose: () => void; onImported: (result: ImportResult) => Promise<void> }) {
  const [preview, setPreview] = useState<ClippingsPreview | null>(null); const [fileName, setFileName] = useState(''); const [choices, setChoices] = useState<Record<string, string>>({}); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [result, setResult] = useState<ImportResult | null>(null); const [batchId, setBatchId] = useState('');
  const [pendingBatches, setPendingBatches] = useState<ImportBatch[] | null>(null);
  const [uploadedBatches, setUploadedBatches] = useState(0);
  const uploadCursor = useRef(0);
  const accumulated = useRef<ImportResult>({ imported: 0, updated: 0, skipped: 0, books: 0, warnings: [] });
  async function selectFile(file?: File) {
    if (!file) return; setError(''); setPreview(null); setResult(null); setFileName(file.name); setBusy(true);
    try { if (file.size > 3 * 1024 * 1024) throw new Error('Choose a clippings file smaller than 3 MB.'); const text = await file.text(); const parsed = await mutate<ClippingsPreview>('/api/clippings/preview', { text }); setPreview(parsed); setBatchId(crypto.randomUUID()); setPendingBatches(null); setUploadedBatches(0); uploadCursor.current = 0; accumulated.current = { imported: 0, updated: 0, skipped: 0, books: 0, warnings: [] }; const initial: Record<string, string> = {}; for (const b of parsed.books) { const candidates = parsed.matches.find(m => m.sourceId === b.sourceId)?.candidates ?? []; initial[b.sourceId] = candidates.length === 1 ? candidates[0].id : candidates.length > 1 ? '' : 'new'; } setChoices(initial); } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  }
  async function importFile() {
    if (!preview) return; setBusy(true); setError('');
    try {
      const batches = pendingBatches ?? prepareClippingsBatches(preview, choices, batchId);
      setPendingBatches(batches);
      while (uploadCursor.current < batches.length) {
        const imported = await mutate<ImportResult>('/api/clippings/import', batches[uploadCursor.current]);
        const current = accumulated.current;
        accumulated.current = {
          imported: current.imported + imported.imported,
          updated: current.updated + imported.updated,
          skipped: current.skipped + imported.skipped,
          books: current.books + imported.books,
          warnings: Array.from(new Set([...current.warnings, ...imported.warnings])),
        };
        uploadCursor.current += 1;
        setUploadedBatches(uploadCursor.current);
      }
      setResult(accumulated.current);
      await onImported(accumulated.current);
    } catch (e) { setError((e as Error).message + ' You can retry safely; completed batches will not be sent again.'); } finally { setBusy(false); }
  }
  const hasUnresolved = preview?.books.some(b => !choices[b.sourceId]);
  return <Modal title="Bring your clippings along." description="Import the My Clippings.txt file from your Kindle." onClose={busy ? () => {} : onClose} wide>{error && <ErrorMessage error={error}/>} {result ? <div className="import-success"><span className="round-icon"><Icon name="check" size={27}/></span><h3>Your words are here.</h3><p>{result.imported} highlights imported · {result.updated} updated · {result.skipped} skipped</p>{result.warnings.length > 0 && <div className="notice warning"><ul>{result.warnings.map((w, i) => <li key={i}>{w}</li>)}</ul></div>}<button className="button primary" onClick={onClose}>Back to your library<Icon name="arrow" size={17}/></button></div> : <><div className="upload-instructions"><Icon name="book" size={22}/><p>Connect your Kindle to your computer with a USB cable. Open its <strong>documents</strong> folder and select <strong>My Clippings.txt</strong>. English Kindle exports are supported.</p></div><label className="file-drop"><Icon name="upload" size={25}/><strong>{fileName || 'Choose your clippings file'}</strong><span>{busy ? 'Reading your passages…' : 'Plain text · up to 3 MB'}</span><input type="file" accept=".txt,text/plain" aria-label="Choose My Clippings.txt" onChange={e => void selectFile(e.target.files?.[0])} disabled={busy || !!pendingBatches}/></label>{preview && <div className="import-preview"><div className="section-heading"><h3>Before they join the shelf</h3><span className="pill subtle">{preview.books.reduce((n, b) => n + b.highlights.length, 0)} highlights</span></div><p className="small muted">Check where each book belongs. Existing highlights are updated when the source and location match.</p>{preview.warnings.length > 0 && <div className="notice warning"><div><strong>A few things to know</strong><ul>{preview.warnings.map((w, i) => <li key={i}>{w}</li>)}</ul></div></div>}{preview.books.length === 0 && <p className="notice">No importable highlights were found in this file.</p>}{preview.books.map(book => { const candidates = preview.matches.find(m => m.sourceId === book.sourceId)?.candidates ?? []; return <div className="import-book" key={book.sourceId}><div><strong>{book.title}</strong><p>{book.author || 'Unknown author'} · {book.highlights.length} highlights</p></div><label><span className="small-label">ADD TO</span><select value={choices[book.sourceId] ?? ''} onChange={e => setChoices(current => ({ ...current, [book.sourceId]: e.target.value }))} disabled={busy || !!pendingBatches} aria-label={`Match ${book.title} to a book`}>{candidates.length > 1 && <option value="">Choose a matching book…</option>}<option value="new">A new book</option>{(candidates.length ? candidates : books).map(b => <option key={b.id} value={b.id}>{b.title} — {b.author || 'Unknown author'}</option>)}</select></label>{book.highlights[0] && <blockquote>{book.highlights[0].text.slice(0, 200)}{book.highlights[0].text.length > 200 ? '…' : ''}</blockquote>}{candidates.length > 1 && !choices[book.sourceId] && <p className="error-text small">More than one book could match. Choose one or create a new book.</p>}</div>; })}<div className="modal-footer"><span className="small muted">{pendingBatches ? `${uploadedBatches} of ${pendingBatches.length} batches saved. Book choices stay fixed for safe retries.` : 'Your saved highlights are never removed by an import.'}</span><button className="button primary" disabled={busy || !preview.books.length || hasUnresolved} onClick={() => void importFile()}>{busy ? 'Importing…' : pendingBatches ? 'Resume import' : 'Add to my library'}<Icon name="arrow" size={17}/></button></div></div>}</>}</Modal>;
}

function Settings({ dashboard, refresh, navigate }: { dashboard: Dashboard; refresh: () => Promise<void>; navigate: (path: string) => void }) {
  const [preferences, setPreferences] = useState<Preferences>({ ...dashboard.preferences }); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState('');
  const browserTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const timezones = Array.from(new Set([browserTimezone, preferences.timezone, 'UTC', ...((Intl as typeof Intl & { supportedValuesOf?: (type: string) => string[] }).supportedValuesOf?.('timeZone') ?? ['America/Los_Angeles', 'America/New_York', 'Europe/London', 'Europe/Paris', 'Asia/Kolkata', 'Asia/Tokyo', 'Australia/Sydney'])]));
  const preferenceValues = (p: Preferences) => [p.intervalDays, p.highlightCount, p.localTime, p.timezone, p.enabled];
  const dirty = JSON.stringify(preferenceValues(preferences)) !== JSON.stringify(preferenceValues(dashboard.preferences));
  async function save(e: React.FormEvent) { e.preventDefault(); setBusy(true); setError(''); setNotice(''); try { const { nextSendAt: _, ...fields } = preferences; const saved = await mutate<Preferences>('/api/preferences', fields, 'PUT'); setPreferences(saved); await refresh(); setNotice(saved.enabled ? `Your rhythm is saved. Your next letter is planned for ${readableDate(saved.nextSendAt, saved.timezone)}.` : 'Your rhythm is saved. Emails are paused until you enable delivery.'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  function update<K extends keyof Preferences>(key: K, value: Preferences[K]) { setPreferences(p => ({ ...p, [key]: value })); setNotice(''); }
  return <><PageHeading eyebrow="MAKE IT YOUR OWN" title="Find your reading rhythm." description="A little every day, or a little less often. There’s no right pace."/>{error && <ErrorMessage error={error}/>} {notice && <div className="notice success" role="status"><Icon name="check" size={18}/>{notice}</div>}<div className="settings-layout"><form className="settings-form" onSubmit={save}><section className="settings-section"><div className="setting-section-title"><span className="step-number">01</span><div><h2>A small helping of good words</h2><p>Choose how much arrives, and how often.</p></div></div><div className="settings-fields"><div className="field"><label htmlFor="highlight-count">Highlights per email</label><div className="number-field"><input id="highlight-count" type="number" min="1" max="20" required value={Number.isFinite(preferences.highlightCount) ? preferences.highlightCount : ''} onChange={e => update('highlightCount', e.target.valueAsNumber)} disabled={busy}/><span>highlights</span></div><p className="field-help">Between 1 and 20. Enough to linger over.</p></div><div className="field"><label htmlFor="interval-days">Send me an email every</label><div className="number-field"><input id="interval-days" type="number" min="1" max="30" required value={Number.isFinite(preferences.intervalDays) ? preferences.intervalDays : ''} onChange={e => update('intervalDays', e.target.valueAsNumber)} disabled={busy}/><span>day{preferences.intervalDays === 1 ? '' : 's'}</span></div><p className="field-help">Between 1 and 30 days.</p></div></div></section><section className="settings-section"><div className="setting-section-title"><span className="step-number">02</span><div><h2>Give your words a moment</h2><p>Morning coffee, a quiet lunch, or an evening pause.</p></div></div><div className="settings-fields time-fields"><div className="field"><label htmlFor="delivery-time">Delivery time</label><input id="delivery-time" type="time" value={preferences.localTime} onChange={e => update('localTime', e.target.value)} required disabled={busy}/><p className="field-help">Within a few minutes of your chosen time.</p></div><div className="field"><label htmlFor="timezone">Timezone</label><select id="timezone" value={preferences.timezone} onChange={e => update('timezone', e.target.value)} disabled={busy}>{timezones.map(tz => <option key={tz} value={tz}>{tz.replaceAll('_', ' ')}</option>)}</select><button type="button" className="text-button small" onClick={() => update('timezone', browserTimezone)} disabled={busy || preferences.timezone === browserTimezone}>Use my current timezone</button></div></div></section><section className="settings-section delivery-section"><div className="setting-section-title"><span className="step-number">03</span><div><h2>Ready when you are</h2><p>You can pause your letters at any time.</p></div></div><label className="toggle-row" htmlFor="delivery-enabled"><span><strong>Email delivery</strong><span>{preferences.enabled ? 'Your passages will arrive on your chosen schedule.' : 'Paused. Your library is here whenever you return.'}</span></span><input type="checkbox" role="switch" id="delivery-enabled" checked={preferences.enabled} onChange={e => update('enabled', e.target.checked)} disabled={busy}/><span className="toggle-track" aria-hidden="true"/></label>{preferences.enabled && dashboard.totals.eligible === 0 && <div className="notice">Add some highlights to your library before your first letter. Empty emails are automatically skipped.</div>}</section><div className="settings-save"><p className="small muted">{dirty ? 'You have unsaved changes.' : 'A rhythm you can always change.'}</p><button className="button primary" type="submit" disabled={busy || !dirty}>{busy ? 'Saving…' : 'Save my rhythm'}<Icon name="check" size={17}/></button></div></form><aside className="settings-aside"><div className="ritual-summary"><Icon name="mail" size={27}/><p>Your little ritual</p><h2>{Number.isFinite(preferences.highlightCount) ? preferences.highlightCount : 'A few'} good thoughts.<br/>{preferences.intervalDays === 1 ? 'Every day.' : `Every ${Number.isFinite(preferences.intervalDays) ? preferences.intervalDays : 'few'} days.`}</h2><p>At {scheduleTime(preferences)}.<br/>A moment to make them yours again.</p><div className="summary-rule"/><p className="small">Delivered to</p><strong className="summary-email">{dashboard.user.email}</strong></div><div className="settings-note"><h3>A little variety, by design.</h3><p>We mix passages across your books and favor words you haven’t seen lately. Hidden highlights and excluded books stay on the shelf.</p><button className="text-button" onClick={() => navigate('/library')}>Curate your library <Icon name="arrow" size={15}/></button></div></aside></div></>;
}

function Connect({ dashboard, refresh }: { dashboard: Dashboard; refresh: () => Promise<void> }) {
  const [pairing, setPairing] = useState<{ code: string; expiresAt: string; appUrl: string } | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [revokeId, setRevokeId] = useState<string | null>(null); const [time, setTime] = useState(Date.now());
  useEffect(() => { if (!pairing) return; const interval = setInterval(() => setTime(Date.now()), 1000); return () => clearInterval(interval); }, [pairing]);
  async function createCode() { setBusy(true); setError(''); try { setPairing(await mutate('/api/pairing')); setTime(Date.now()); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function revoke(id: string) { setBusy(true); setError(''); try { await mutate(`/api/extension-tokens/${id}`, undefined, 'DELETE'); setRevokeId(null); setNotice('This extension connection has been revoked. Your saved highlights are still in your library.'); await refresh(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function copy(text: string) { try { await navigator.clipboard.writeText(text); setNotice('Pairing code copied. Paste it into the Writefool extension.'); } catch { setNotice('Select the pairing code and copy it manually.'); } }
  const secondsRemaining = pairing ? Math.max(0, Math.floor((new Date(pairing.expiresAt).getTime() - time) / 1000)) : 0;
  return <><PageHeading eyebrow="A BRIDGE TO YOUR BOOKS" title="Bring your Kindle along." description="Your highlights make the journey. Your Amazon login stays in your browser."/>{error && <ErrorMessage error={error}/>} {notice && <div className="notice success" role="status">{notice}</div>}<div className="connect-layout"><section className="connect-main"><div className="connection-diagram" aria-hidden="true"><div><Icon name="book" size={31}/><span>Your Kindle</span></div><span className="connection-dots">·········</span><Icon name="arrow" size={21}/><span className="connection-dots">·········</span><div><Icon name="mail" size={31}/><span>Your letter</span></div></div><ol className="connect-steps"><li><span className="step-number">01</span><div><h2>Add the Writefool extension</h2><p>This personal version installs directly in Chrome. Build it from the project, then load the extension folder.</p><div className="code-line"><code>{window.location.origin === 'http://localhost:5183' ? 'pnpm build:extension' : `WRITEFOOL_APP_URL=${window.location.origin} pnpm build:extension`}</code></div><p className="small">Open <code>chrome://extensions</code>, enable <strong>Developer mode</strong>, choose <strong>Load unpacked</strong>, and select <code>extension/dist</code> inside this project.</p></div></li><li><span className="step-number">02</span><div><h2>Connect it to your bookshelf</h2><p>Open the Writefool extension. Check that its app address matches the one below, then enter your one-time pairing code.</p><label className="small-label" htmlFor="app-url">APP ADDRESS</label><input id="app-url" readOnly value={pairing?.appUrl ?? window.location.origin} onFocus={e => e.target.select()}/>{pairing ? <div className={`pairing-box ${!secondsRemaining ? 'expired' : ''}`}><span className="small-label">YOUR ONE-TIME CODE</span><div className="pairing-code"><code>{pairing.code}</code><button className="button secondary small-button" disabled={!secondsRemaining} onClick={() => void copy(pairing.code)}>Copy</button></div><span className="small muted" role="status">{secondsRemaining ? `Expires in ${Math.floor(secondsRemaining / 60)}:${String(secondsRemaining % 60).padStart(2, '0')}` : 'This code has expired. Generate a fresh one below.'}</span><button className="text-button small" onClick={() => void createCode()} disabled={busy}>Generate a new code</button></div> : <button className="button primary" onClick={() => void createCode()} disabled={busy}>{busy ? 'Creating code…' : 'Create pairing code'}<Icon name="link" size={17}/></button>}</div></li><li><span className="step-number">03</span><div><h2>Let your highlights find their way here</h2><p>Sign in to your US Kindle notebook. After pairing, check and confirm your Kindle account in the extension. Other Amazon accounts will pause imports. Choose <strong>Sync highlights</strong> in the extension to try again or bring in new passages. After that, it checks daily when Chrome is open.</p><a className="button secondary" href="https://read.amazon.com/notebook" target="_blank" rel="noreferrer">Open Kindle notebook<Icon name="arrow" size={17}/></a></div></li></ol></section><aside className="connect-aside"><section className="connection-status"><div className="section-heading"><h2>Connection status</h2><span className={`status-dot ${dashboard.sync.connected ? 'green' : ''}`}/></div><strong className="connection-status-label">{dashboard.sync.status.startsWith('account_') ? 'Kindle sync paused' : dashboard.sync.status === 'login_required' ? 'Amazon sign-in needed' : dashboard.sync.status === 'syncing' ? 'Bringing your books over…' : dashboard.sync.status === 'error' ? 'The last sync needs attention' : dashboard.sync.connected ? 'You’re connected' : 'Waiting to connect'}</strong><p>{dashboard.sync.message || (dashboard.sync.connected ? `Last successful import: ${relativeDate(dashboard.sync.lastSuccessAt)}.` : 'Pair your extension to bring in your first highlights.')}</p>{dashboard.sync.status === 'syncing' && <progress max="100" value={dashboard.sync.progress} aria-label="Kindle import progress"/>}<button className="text-button" onClick={() => void refresh().catch(e => setError((e as Error).message))}><Icon name="refresh" size={14}/>Refresh status</button></section><div className="settings-note"><h3>Good to know</h3><p>Emails keep arriving with Chrome closed, using highlights already in your library.</p><p>Amazon purchases appear in the notebook. For personal documents and other passages, use the clippings import in your library.</p></div>{dashboard.extensionTokens.length > 0 && <section className="paired-devices"><h3>Connected extensions</h3>{dashboard.extensionTokens.map((token, i) => <div className="paired-device" key={token.id}><div><strong>Chrome extension {dashboard.extensionTokens.length > 1 ? i + 1 : ''}</strong><p>Paired {readableDate(token.createdAt, undefined, false)}</p><p>Last used {relativeDate(token.lastUsedAt)}</p></div><button className="text-button error-text" onClick={() => setRevokeId(token.id)}>Revoke</button></div>)}</section>}</aside></div>{revokeId && <Modal title="Disconnect this extension?" description="It will need a new pairing code to import again. Your saved highlights and email schedule remain available." onClose={() => setRevokeId(null)}><div className="modal-footer"><button className="button secondary" onClick={() => setRevokeId(null)} disabled={busy}>Keep connected</button><button className="button primary" onClick={() => void revoke(revokeId)} disabled={busy}>{busy ? 'Disconnecting…' : 'Disconnect extension'}</button></div></Modal>}</>;
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
